                    B::and_(B::and_(B::shuffle(c.byte_1_high, B::high_nibble(prev1, c.nibble)),
                                    B::shuffle(c.byte_1_low, B::and_(prev1, c.nibble))),
                            B::shuffle(c.byte_2_high, B::high_nibble(input, c.nibble)));
